const storage = createIsomorphicFn()
  .server((key: string) => {
    // 서버: 파일 기반 캐시
    const fs = require('node:fs')
    return JSON.parse(fs.readFileSync('.cache', 'utf-8'))[key]
  })
  .client((key: string) => {
    // 클라이언트: localStorage
    return JSON.parse(localStorage.getItem(key) || 'null')
  })

