// ❌ loader가 서버 전용이라고 가정
export const Route = createFileRoute('/users')({
  loader: () => {
    // 이것은 서버와 클라이언트 양쪽 모두에서 실행돼요!
    const secret = process.env.SECRET // 클라이언트에 노출됨
    return fetch(`/api/users?key=${secret}`)
  },
})

// ✅ 서버 전용 작업에는 서버 함수 사용
const getUsersSecurely = createServerFn().handler(() => {
  const secret = process.env.SECRET // 서버 전용
  return fetch(`/api/users?key=${secret}`)
})

export const Route = createFileRoute('/users')({
  loader: () => getUsersSecurely(), // 서버 함수로의 isomorphic 호출
})

